+          ctx.strokeStyle = i % 2 ? '#ddad60' : '#edc375';
+          ctx.lineWidth = bw * .007;
+          ctx.stroke();
+          ctx.strokeStyle = 'rgba(255, 228, 155, .34)';
+          ctx.lineWidth = bw * .0018;
+          ctx.stroke();
+        }
+        ctx.restore();
+      }
+
+      function drawBokChoy(bw) {
+        ctx.save();
+        ctx.translate(-bw * .245, -bw * .018);
+        ctx.rotate(-.14);
+
+        // Pale stems.
+        for (let i = 0; i < 3; i++) {
