+          ctx.lineTo(0, -bw * .072);
+          ctx.stroke();
+          ctx.restore();
+        }
+        ctx.restore();
+      }
+
+      function drawMushrooms(bw) {
+        const mushrooms = [
+          { x: .095, y: -.045, s: 1, r: -.14 },
+          { x: .205, y: .018, s: .83, r: .16 }
