+          cap.addColorStop(0, '#a6754f');
+          cap.addColorStop(.3, '#6e442f');
+          cap.addColorStop(.72, '#38251e');
+          cap.addColorStop(1, '#1d1715');
+          ctx.fillStyle = cap;
+          ctx.beginPath();
+          ctx.arc(0, 0, bw * .085, 0, TAU);
+          ctx.fill();
+          ctx.strokeStyle = 'rgba(226, 184, 134, .25)';
+          ctx.lineWidth = bw * .004;
+          for (let i = 0; i < 5; i++) {
+            const a = i * TAU / 5 + .25;
