+          ctx.moveTo(-size, -size * .36);
+          ctx.lineTo(-size * .58, -size * .72);
+          ctx.lineTo(size * 1.06, -size * .52);
+          ctx.lineTo(size, -size * .36);
+          ctx.closePath();
+          ctx.fill();
+          ctx.fillStyle = '#89552e';
+          ctx.beginPath();
+          ctx.moveTo(size, -size * .36);
+          ctx.lineTo(size * 1.06, -size * .52);
+          ctx.lineTo(size * 1.05, size * .22);
+          ctx.lineTo(size, size * .36);
+          ctx.closePath();
+          ctx.fill();
+          ctx.restore();
+        }
+      }
+
+      function drawScallions(bw) {
+        for (const s of scallions) {
+          ctx.save();
+          ctx.translate(s.x * bw, s.y * bw * .33);
+          ctx.rotate(s.rot);
+          ctx.scale(1, .55);
+          ctx.fillStyle = s.shade > .5 ? '#8fb94f' : '#5f9238';
