+      background:
+        linear-gradient(115deg, rgba(255,255,255,.018), transparent 24%, rgba(0,0,0,.05) 78%),
+        radial-gradient(ellipse at center, transparent 40%, rgba(0,0,0,.28) 100%);
+      mix-blend-mode: soft-light;
+    }
+
+    @media (prefers-reduced-motion: reduce) {
+      body { cursor: default; }
+    }
+  </style>
+</head>
+<body>
+  <canvas id="scene" role="img" aria-label="A steaming bowl of vegan ramen in a quiet, dark room"></canvas>
+
+  <script>
+    (() => {
+      'use strict';
+
+      const canvas = document.getElementById('scene');
+      const ctx = canvas.getContext('2d', { alpha: false });
+      const reducedQuery = matchMedia('(prefers-reduced-motion: reduce)');
+      const TAU = Math.PI * 2;
+
+      let width = 0;
+      let height = 0;
+      let dpr = 1;
+      let reducedMotion = reducedQuery.matches;
+      let animationFrame = 0;
+      let lastTime = 0;
+
+      const pointer = {
+        x: 0, y: 0,
+        tx: 0, ty: 0,
+        lightX: 0
+      };
+
+      const rand = mulberry32(271828);
+      const ceramicSpecks = Array.from({ length: 95 }, () => ({
+        x: rand(), y: rand(), r: .3 + rand() * .8, a: .025 + rand() * .055
+      }));
+      const brothFlecks = Array.from({ length: 42 }, () => ({
+        x: rand() * 2 - 1,
+        y: rand() * 2 - 1,
+        r: .5 + rand() * 1.4,
+        phase: rand() * TAU,
+        kind: rand()
+      })).filter(p => p.x * p.x + p.y * p.y < 1);
+      const scallions = Array.from({ length: 23 }, () => ({
+        x: (rand() * 2 - 1) * .25,
+        y: (rand() * 2 - 1) * .35,
+        rx: .008 + rand() * .008,
+        ry: .004 + rand() * .004,
+        rot: (rand() - .5) * 1.8,
+        shade: rand()
+      }));
+      const oilDrops = Array.from({ length: 18 }, () => ({
+        x: (rand() * 2 - 1) * .38,
+        y: (rand() * 2 - 1) * .47,
+        r: .004 + rand() * .008,
+        phase: rand() * TAU
+      }));
+
+      function mulberry32(seed) {
+        return function () {
+          let t = seed += 0x6D2B79F5;
+          t = Math.imul(t ^ t >>> 15, t | 1);
+          t ^= t + Math.imul(t ^ t >>> 7, t | 61);
+          return ((t ^ t >>> 14) >>> 0) / 4294967296;
+        };
+      }
+
+      function resize() {
+        width = innerWidth;
+        height = innerHeight;
+        dpr = Math.min(devicePixelRatio || 1, 2);
+        canvas.width = Math.round(width * dpr);
+        canvas.height = Math.round(height * dpr);
+        canvas.style.width = width + 'px';
+        canvas.style.height = height + 'px';
+        render(reducedMotion ? 7.2 : lastTime);
+      }
+
+      function ellipsePath(x, y, rx, ry) {
+        ctx.beginPath();
+        ctx.ellipse(x, y, rx, ry, 0, 0, TAU);
+      }
+
+      function glowEllipse(x, y, rx, ry, color, blur, alpha = 1) {
+        ctx.save();
