+        ctx.fill();
+        ctx.restore();
+      }
+
+      function drawBackground(cx, cy, bowlWidth) {
+        const lightX = cx + pointer.lightX * width * .08;
+        const wall = ctx.createRadialGradient(
+          lightX, cy - bowlWidth * .28, 0,
+          lightX, cy - bowlWidth * .18, Math.max(width, height) * .72
