+        table.addColorStop(.12, 'rgba(6, 8, 7, .55)');
+        table.addColorStop(1, '#050606');
+        ctx.fillStyle = table;
+        ctx.fillRect(0, tableY - bowlWidth * .04, width, height - tableY + bowlWidth * .04);
