+      }
+
+      function drawSteam(bw, t, lean) {
+        ctx.save();
+        ctx.globalCompositeOperation = 'screen';
+        ctx.lineCap = 'round';
+
+        const tendrils = [
+          { x: -.27, phase: .4, h: .48, drift: .035, width: .006, alpha: .22 },
+          { x: -.14, phase: 2.2, h: .63, drift: .055, width: .008, alpha: .30 },
