+        broth.addColorStop(.22, '#82401f');
+        broth.addColorStop(.58, '#4c2519');
+        broth.addColorStop(1, '#1b1712');
+        ctx.fillStyle = broth;
+        ellipsePath(0, 0, rx, ry);
+        ctx.fill();
+
+        ctx.save();
+        ellipsePath(0, 0, rx, ry);
+        ctx.clip();
+
+        // Slow, concentric surface movement.
+        ctx.save();
+        ctx.globalAlpha = .12;
+        ctx.strokeStyle = '#f0a052';
+        ctx.lineWidth = Math.max(.7, bw * .0015);
+        for (let i = 0; i < 3; i++) {
+          const swell = .5 + .5 * Math.sin(t * .8 + i * 1.8);
+          ctx.beginPath();
+          ctx.ellipse(
+            bw * (-.08 + i * .11), bw * (-.016 + i * .008),
