+        // Small broth solids and spice catch the low light.
+        for (const f of brothFlecks) {
+          const x = f.x * rx * .88;
+          const y = f.y * ry * .76;
+          ctx.fillStyle = f.kind > .52 ? 'rgba(244,187,96,.24)' : 'rgba(32,17,11,.34)';
+          ctx.beginPath();
+          ctx.arc(x, y, f.r * bw / 540, 0, TAU);
+          ctx.fill();
+        }
+
+        for (const d of oilDrops) {
+          const shimmer = .65 + .35 * Math.sin(t * .65 + d.phase);
+          const x = d.x * bw;
+          const y = d.y * ry;
