+        ctx.restore();
+      }
+
+      function drawNoodles(bw, t) {
+        ctx.save();
+        ctx.lineCap = 'round';
+        ctx.lineJoin = 'round';
+        const noodles = [
+          [-.35,-.03, -.19,-.11, .02,-.075, .18,.01],
+          [-.29,.045, -.14,-.04, .05,-.055, .29,-.018],
+          [-.24,.075, -.10,.015, .13,-.008, .33,.038],
+          [-.20,.095, -.02,.042, .16,.027, .31,.068],
+          [-.37,.015, -.23,.085, -.05,.105, .13,.045],
+          [-.16,-.085, -.03,-.12, .11,-.092, .25,-.055],
+          [-.08,.105, .04,.065, .16,.055, .27,.086]
+        ];
+        const shift = Math.sin(t * .53) * bw * .0015;
+        for (let i = 0; i < noodles.length; i++) {
+          const n = noodles[i];
+          ctx.strokeStyle = 'rgba(70, 35, 13, .42)';
+          ctx.lineWidth = bw * .012;
+          ctx.beginPath();
+          ctx.moveTo(n[0] * bw, n[1] * bw + shift);
+          ctx.bezierCurveTo(n[2] * bw, n[3] * bw, n[4] * bw, n[5] * bw, n[6] * bw, n[7] * bw);
