+          cap.addColorStop(0, '#a6754f');
+          cap.addColorStop(.3, '#6e442f');
+          cap.addColorStop(.72, '#38251e');
+          cap.addColorStop(1, '#1d1715');
+          ctx.fillStyle = cap;
+          ctx.beginPath();
+          ctx.arc(0, 0, bw * .085, 0, TAU);
+          ctx.fill();
+          ctx.strokeStyle = 'rgba(226, 184, 134, .25)';
+          ctx.lineWidth = bw * .004;
+          for (let i = 0; i < 5; i++) {
+            const a = i * TAU / 5 + .25;
+            ctx.beginPath();
+            ctx.moveTo(0, 0);
+            ctx.lineTo(Math.cos(a) * bw * .067, Math.sin(a) * bw * .067);
+            ctx.stroke();
+          }
+          ctx.restore();
+        }
+      }
+
+      function drawTofu(bw) {
+        const cubes = [
+          { x: -.055, y: -.035, s: .066, r: -.08 },
+          { x: .035, y: .052, s: .058, r: .12 }
+        ];
+        for (const c of cubes) {
+          ctx.save();
+          ctx.translate(c.x * bw, c.y * bw);
+          ctx.rotate(c.r);
+          const size = c.s * bw;
+          ctx.fillStyle = '#bf8a4e';
+          ctx.fillRect(-size, -size * .36, size * 2, size * .72);
+          ctx.fillStyle = '#e2ad65';
+          ctx.beginPath();
+          ctx.moveTo(-size, -size * .36);
+          ctx.lineTo(-size * .58, -size * .72);
+          ctx.lineTo(size * 1.06, -size * .52);
+          ctx.lineTo(size, -size * .36);
+          ctx.closePath();
+          ctx.fill();
+          ctx.fillStyle = '#89552e';
+          ctx.beginPath();
+          ctx.moveTo(size, -size * .36);
+          ctx.lineTo(size * 1.06, -size * .52);
+          ctx.lineTo(size * 1.05, size * .22);
+          ctx.lineTo(size, size * .36);
+          ctx.closePath();
+          ctx.fill();
+          ctx.restore();
+        }
+      }
+
+      function drawScallions(bw) {
+        for (const s of scallions) {
+          ctx.save();
+          ctx.translate(s.x * bw, s.y * bw * .33);
+          ctx.rotate(s.rot);
+          ctx.scale(1, .55);
+          ctx.fillStyle = s.shade > .5 ? '#8fb94f' : '#5f9238';
+          ctx.beginPath();
+          ctx.ellipse(0, 0, s.rx * bw, s.ry * bw, 0, 0, TAU);
+          ctx.fill();
+          ctx.fillStyle = '#223a1c';
+          ctx.beginPath();
+          ctx.ellipse(0, 0, s.rx * bw * .48, s.ry * bw * .45, 0, 0, TAU);
+          ctx.fill();
+          ctx.restore();
+        }
+      }
+
+      function render(timeMs = 0) {
+        const t = timeMs * .001;
+        lastTime = timeMs;
+
+        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
+        ctx.clearRect(0, 0, width, height);
+
+        const landscape = width > height;
+        const bw = Math.min(width * (landscape ? .64 : .88), height * (landscape ? .78 : .54), 690);
+        const cx = width * .5;
+        const cy = height * (landscape ? .61 : .62);
