+        if (!reducedMotion) {
+          pointer.x += (pointer.tx - pointer.x) * .042;
+          pointer.y += (pointer.ty - pointer.y) * .042;
+          pointer.lightX += (pointer.tx - pointer.lightX) * .025;
+        } else {
+          pointer.x = pointer.y = pointer.lightX = 0;
+        }
+
+        drawBackground(cx, cy, bw);
+
+        const breathe = reducedMotion ? 0 : Math.sin(t * .78) * Math.min(1.8, bw * .0025);
+        const shiftX = pointer.x * Math.min(13, bw * .018);
+        const shiftY = pointer.y * Math.min(5, bw * .007) + breathe;
+
+        ctx.save();
+        ctx.translate(cx + shiftX, cy + shiftY);
+        drawSteam(bw, t, pointer.x);
+        drawBowlShadow(bw);
+        drawBowlBody(bw);
+        drawBrothAndToppings(bw, t);
+        ctx.restore();
+
+        // A near-invisible film grain keeps large gradients from feeling digital.
+        ctx.save();
+        ctx.globalAlpha = .045;
+        ctx.fillStyle = '#d8cdbb';
+        const grainSize = Math.max(3, Math.floor(Math.min(width, height) / 180));
+        const offset = reducedMotion ? 3 : Math.floor(t * 7) % grainSize;
+        for (let y = offset; y < height; y += grainSize * 3) {
+          for (let x = (y * 13) % (grainSize * 7); x < width; x += grainSize * 7) {
+            ctx.fillRect(x, y, .55, .55);
+          }
+        }
+        ctx.restore();
+
+        if (!reducedMotion) animationFrame = requestAnimationFrame(render);
+      }
+
+      function onPointerMove(event) {
+        if (reducedMotion) return;
+        pointer.tx = Math.max(-1, Math.min(1, (event.clientX / width - .5) * 2));
+        pointer.ty = Math.max(-1, Math.min(1, (event.clientY / height - .5) * 2));
+      }
+
+      function onMotionPreferenceChange(event) {
+        reducedMotion = event.matches;
+        cancelAnimationFrame(animationFrame);
+        animationFrame = 0;
+        pointer.tx = pointer.ty = 0;
+        render(reducedMotion ? 7200 : performance.now());
+      }
+
+      addEventListener('resize', resize, { passive: true });
+      addEventListener('pointermove', onPointerMove, { passive: true });
+      addEventListener('pointerleave', () => { pointer.tx = pointer.ty = 0; }, { passive: true });
+      reducedQuery.addEventListener('change', onMotionPreferenceChange);
+
+      resize();
+      if (!reducedMotion) animationFrame = requestAnimationFrame(render);
+    })();
+  </script>
+</body>
+</html>

